package com.secure.documentwallet;

import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;

public class VaultSettingsActivity extends FragmentActivity {
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}LinearLayout page=VaultPageUi.page(this);LinearLayout head=VaultPageUi.header(this,"My Vault Settings","Security, appearance, access, and tools");FrameLayout lock=VaultPageUi.iconButtonView(this,"shield","Lock Vault");lock.setOnClickListener(v->{SecureCache.clear(this);Session.lock();startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();});head.addView(lock,new LinearLayout.LayoutParams(Ui.dp(this,36),Ui.dp(this,36)));page.addView(head);page.addView(VaultPageUi.section(this,"Protection"));entry(page,"shield","Security And Backup","Encryption, recovery, and vault health",VaultHealthActivity.class);entry(page,"user","Backup Account And PC Access","Recovery code and browser portal",AccountDevicesActivity.class);entry(page,"image","Appearance","Vault themes",AppearanceActivity.class);page.addView(VaultPageUi.section(this,"Vault Tools"));entry(page,"clock","Expiry Centre","Renewals and important dates",ExpiryCentreActivity.class);entry(page,"share","Export A Document","Create a temporary PDF copy",SecureShareHubActivity.class);entry(page,"info","Essential Documents","Your private emergency shortlist",EmergencyAccessActivity.class);entry(page,"clock","Vault Activity","Document and security history",VaultActivityTimelineActivity.class);entry(page,"download","App Updates","OTA downloads and release information",AppUpdatesActivity.class);setContentView(VaultPageUi.screen(this,page,"profile"));}
 private void entry(LinearLayout page,String icon,String title,String detail,Class<?> target){LinearLayout row=VaultPageUi.iconRow(this,icon,title,detail);row.setOnClickListener(v->startActivity(new Intent(this,target)));VaultPageUi.addRow(page,row);}
}
